def dump(path, d):
    with open(path, 'w', encoding='utf-8') as fh:
        json.dump(d, fh, ensure_ascii=False, indent=1); fh.write('\n')
ph = lambda s: sorted(set(re.findall(r'\{\w+\}', s)))
# 1. The TX keys (once): before the table's end marker; a key already there keeps its text.
tp = os.path.join(ROOT, 'bramblewood-texts.js'); src = open(tp, encoding='utf-8').read()
add = ''.join('  ' + json.dumps(k) + ': ' + json.dumps(en, ensure_ascii=False) + ',\n' for k, en, _ in K if ('"' + k + '":') not in src)
if add:
    end = '\n}/*TEXT-TABLE-END*/'; assert src.count(end) == 1
    i = src.index(end); src = src[:i] + ',\n' + add.rstrip(',\n') + src[i:]
    open(tp, 'w', encoding='utf-8').write(src)
for k, en, _ in K: assert ('"' + k + '": ' + json.dumps(en, ensure_ascii=False)) in src, k
# 2. The 12 packs, keyed by the English text.
for i, code in enumerate(CODES):
    path = os.path.join(ROOT, 'lang', code + '.json'); pack = json.load(open(path, encoding='utf-8'))
    for k, en, row in K:
        assert len(row) == len(CODES) and ph(en) == ph(row[i]), (code, en)
        if en in pack: continue  # an older, reviewed row wins
        pack[en] = row[i]
    dump(path, pack)
print('wrote', len(CODES), 'packs:', len(K), 'texts each;', 'added keys' if add else 'keys already there')
